/// One DDC preset: AD9361 sample-rate choice + matching
/// 3-stage FIR coefficient tables + decimation factors.
/// `sample_rate_hz / (decim1 * decim2 * decim3)` is always
/// 62 500 Hz by construction.
pub struct DdcPreset {
    pub name: &'static str,
    pub sample_rate_hz: u32,
    pub rf_bandwidth_hz: u32,
    pub decim1: usize,
    pub decim2: usize,
    pub decim3: usize,
    pub fir1_coeffs: &'static [i32],
    pub fir2_coeffs: &'static [i32],
    pub fir3_coeffs: &'static [i32],
    /// Worst-case cascaded rejection at 25 kHz offset from the
    /// channel center (the LsmDecimator2 fold-back hotspot).
    /// Ships below -55 dB by build-time enforcement.
    pub rejection_25k_db: f32,
}

/// Total DDC decimation for this preset.
impl DdcPreset {
    pub const fn total_decim(&self) -> usize {
        self.decim1 * self.decim2 * self.decim3
    }
    /// Half of the addressable NCO window (= sample_rate/2).
    pub const fn nco_half_window_hz(&self) -> u32 {
        self.sample_rate_hz / 2
    }
}

